package com.nextaicommerce.platform.fba;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import org.springframework.jdbc.core.JdbcTemplate;import java.util.UUID;import tools.jackson.databind.ObjectMapper;
class FbaReplenishmentOwnershipTest {
 @Test void preMigrationRuntimeNeverQueriesAbsentPlanningTable(){var jdbc=mock(JdbcTemplate.class);var repository=new FbaDepletionRepository(jdbc,new ObjectMapper());when(jdbc.queryForObject(startsWith("SELECT to_regclass"),eq(Boolean.class))).thenReturn(false);assertFalse(repository.managedByReplenishment(UUID.randomUUID(),UUID.randomUUID(),"FBA"));verify(jdbc,never()).queryForObject(contains("SELECT EXISTS(SELECT 1 FROM fba_replenishment_allocations"),eq(Boolean.class),any(Object[].class));}
 @Test void persistentOwnershipBlocksSecondDepletionWithoutFeatureFlag(){var jdbc=mock(JdbcTemplate.class);var repository=new FbaDepletionRepository(jdbc,new ObjectMapper());UUID tenant=UUID.randomUUID(),store=UUID.randomUUID();when(jdbc.queryForObject(startsWith("SELECT to_regclass"),eq(Boolean.class))).thenReturn(true);when(jdbc.queryForObject(startsWith("SELECT EXISTS(SELECT 1 FROM fba_replenishment_allocations"),eq(Boolean.class),eq(tenant),eq(store),eq("FBA"))).thenReturn(true);assertTrue(repository.managedByReplenishment(tenant,store,"FBA"));verify(jdbc).queryForObject(contains("tenant_id=? AND marketplace_connection_id=? AND amazon_shipment_id=?"),eq(Boolean.class),eq(tenant),eq(store),eq("FBA"));}
}
